            // 核心解析函数
            function parseSheet(rawData) {
                try {
                    const data = {
                        main_content: '',
                        status_block: [],
                        chapter_information: [],
                        options: [] // 新增：用于存储选项
                    };

                    const mainContentMatch = rawData.match(/<main_content>([\s\S]*?)<\/main_content>/);
                    const statusBlockMatch = rawData.match(/<status_block>([\s\S]*?)<\/status_block>/);
                    const chapterInfoMatch = rawData.match(/<chapter_information>([\s\S]*?)<\/chapter_information>/);
                    const optionBlockMatch = rawData.match(/<option>([\s\S]*?)<\/option>/); // 新增：匹配选项块

                    if (mainContentMatch) {
                        data.main_content = mainContentMatch[1].trim().replace(/<!--[\s\S]*?-->/g, '');
                    }

                    if (statusBlockMatch) {
                        statusBlockMatch[1].trim().split('\n').forEach(line => {
                            const parts = line.split('|').map(p => p.trim());
                            if (parts.length >= 2) data.status_block.push({ key: parts[0], value: parts.slice(1).join('|') });
                        });
                    }

                    if (chapterInfoMatch) {
                        chapterInfoMatch[1].trim().split('\n').forEach(line => {
                            const parts = line.split('|').map(p => p.trim());
                            if (parts.length >= 2) data.chapter_information.push({ key: parts[0], value: parts.slice(1).join('|') });
                        });
                    }

                    // 新增：解析选项
                    if (optionBlockMatch) {
                        optionBlockMatch[1].trim().split('\n').forEach(line => {
                            const parts = line.split('|').map(p => p.trim());
                            if (parts.length >= 2) data.options.push({ key: parts[0], value: parts.slice(1).join('|') });
                        });
