                            optionEl.dataset.key = item.key;
                            optionEl.dataset.value = item.value;
                            optionEl.innerHTML = `<span class="choice-text">${item.value}</span>`;
                            optionsContainer.appendChild(optionEl);
                        });
                        optionsContainer.style.display = 'block';
                    } else {
                        optionsContainer.style.display = 'none'; // 如果没有选项则隐藏容器
                    }
                }
            }

            // 新增：处理玩家选择点击的核心函数
            function handlePlayerChoiceClick() {
                const choicesContainer = document.querySelector('.player-choices');
                if (!choicesContainer) return;

                choicesContainer.addEventListener('click', function(event) {
                    const choiceOption = event.target.closest('.choice-option');

                    if (choiceOption && !choiceOption.classList.contains('disabled')) {
                        const choiceText = choiceOption.querySelector('.choice-text').textContent.trim();
                        const messageToSend = `{{user}}决定 ${choiceText}`;

                        try {
                            const stInput = window.parent.document.querySelector('#send_textarea, #chat_input textarea, #user_input');
                            const stSendButton = window.parent.document.querySelector('#send_but, #send_button, #submit_button');

                            if (stInput && stSendButton) {
                                stInput.value = messageToSend;
                                stInput.dispatchEvent(new Event('input', { bubbles: true }));
                                stSendButton.click();
                            } else {
                                throw new Error('SillyTavern UI elements not found. Using fallback.');
                            }
                        } catch (e) {
                            console.warn('Could not send to SillyTavern. Copying to clipboard instead.', e.message);
                            navigator.clipboard.writeText(messageToSend).then(() => {
                                const originalKey = choiceOption.dataset.key;
                                const originalValue = choiceOption.dataset.value;
                                choiceOption.innerHTML = `<span class="choice-text" style="color: var(--accent);">已复制到剪贴板!</span>`;
                                choiceOption.classList.add('disabled');

                                setTimeout(() => {
                                    choiceOption.innerHTML = `<span class="choice-text">${originalValue}</span>`;
                                    choiceOption.classList.remove('disabled');
                                }, 2000);
                            }).catch(err => {
                                console.error('Failed to copy text: ', err);
                            });
                        }
                    }
                });
            }

            // --- 执行 ---
            const rawData = document.getElementById('injected-data-container').textContent;
            const parsedData = parseSheet(rawData);
            render(parsedData);
            handlePlayerChoiceClick(); // 附加事件监听器
        });
    </script>
